<script setup>
import { computed, ref, watch } from 'vue'
import { router, usePage } from '@/user/inertia'
import PageLayout from '../../layouts/PageLayout.vue'
import CopyValue from '@/pages/themes/partials/CopyValue.vue'

const page = usePage()

const balance = computed(() => Number(page.props.balance ?? 0))
const selectedWallet = computed(() => page.props.selectedWallet ?? null)
const usdtWallet = computed(() => page.props.usdtWallet ?? null)
const walletCount = computed(() => page.props.walletCount ?? 0)
const recentWithdraws = computed(() => page.props.recentWithdraws ?? [])
const settings = computed(() => page.props.settings ?? {})

const activeMethod = ref('EWALLET')

const amount = ref('') 
const usdtAmount = ref('') 

const showPasswordPopup = ref(false)
const password = ref('')
const showPassword = ref(false)
const submitting = ref(false)

const isUsdt = computed(() => activeMethod.value === 'USDT')
const usdtRate = computed(() => Number(settings.value.usdt_rate ?? 125))

const currentWallet = computed(() => {
  return isUsdt.value ? usdtWallet.value : selectedWallet.value
})

const currentWalletLabel = computed(() => {
  if (!currentWallet.value) return 'Wallet'
  return currentWallet.value.type || 'Wallet'
})

const currentWalletNumber = computed(() => {
  if (!currentWallet.value) return 'Select wallet'
  return currentWallet.value.masked_account || currentWallet.value.account_number || 'Select wallet'
})

const formatAmount = (value) => {
  const num = Number(value ?? 0)
  return Number.isNaN(num) ? '0.00' : num.toFixed(2)
}

const numericAmount = computed(() => {
  const value = Number(amount.value || 0)
  return Number.isNaN(value) ? 0 : value
})

const numericUsdtAmount = computed(() => {
  const value = Number(usdtAmount.value || 0)
  return Number.isNaN(value) ? 0 : value
})

const withdrawInfo = computed(() => ({
  withdrawTime: isUsdt.value ? '00:00-23:50' : settings.value.withdraw_time,
  min: isUsdt.value ? Number(settings.value.min_usdt_amount ?? 10) : Number(settings.value.min_amount ?? 300),
  max: isUsdt.value ? Number(settings.value.max_usdt_amount ?? 10000) : Number(settings.value.max_amount ?? 25000),
}))

const minAmountBdt = computed(() => {
  return isUsdt.value
    ? Number(settings.value.min_usdt_amount ?? 10) * usdtRate.value
    : Number(settings.value.min_amount ?? 300)
})

const maxAmountBdt = computed(() => {
  return isUsdt.value
    ? Number(settings.value.max_usdt_amount ?? 10000) * usdtRate.value
    : Number(settings.value.max_amount ?? 25000)
})

const receivedAmount = computed(() => {
  if (!numericAmount.value || numericAmount.value <= 0) {
    return isUsdt.value ? '0.00 USDT' : '৳0.00'
  }

  if (isUsdt.value) {
    return `${(numericAmount.value / usdtRate.value).toFixed(2)} USDT`
  }

  return `৳${numericAmount.value.toFixed(2)}`
})

const conversionText = computed(() => {
  if (!isUsdt.value) return ''
  return `Rate: 1 USDT = ৳${formatAmount(usdtRate.value)}`
})

const infinityWalletAmount = computed(() => {
  if (!isUsdt.value) return ''
  return `${(balance.value / usdtRate.value).toFixed(2)} USDT`
})

const amountError = computed(() => {
  if (!numericAmount.value) return ''

  if (numericAmount.value < minAmountBdt.value) {
    return isUsdt.value
      ? `Minimum withdrawal is ${withdrawInfo.value.min} USDT`
      : `Minimum withdrawal is ৳${formatAmount(withdrawInfo.value.min)}`
  }

  if (numericAmount.value > maxAmountBdt.value) {
    return isUsdt.value
      ? `Maximum withdrawal is ${withdrawInfo.value.max} USDT`
      : `Maximum withdrawal is ৳${formatAmount(withdrawInfo.value.max)}`
  }

  if (numericAmount.value > balance.value) {
    return 'Insufficient balance'
  }

  return ''
})

const setBdtAmount = (value) => {
  amount.value = value === '' ? '' : String(value)
}

const setUsdtAmount = (value) => {
  usdtAmount.value = value === '' ? '' : String(value)
}

const onBdtInput = (event) => {
  const value = event.target.value
  setBdtAmount(value)

  if (!value || Number(value) <= 0) {
    setUsdtAmount('')
    return
  }

  setUsdtAmount((Number(value) / usdtRate.value).toFixed(2))
}

const onUsdtInput = (event) => {
  const value = event.target.value
  setUsdtAmount(value)

  if (!value || Number(value) <= 0) {
    setBdtAmount('')
    return
  }

  setBdtAmount((Number(value) * usdtRate.value).toFixed(2))
}

watch(isUsdt, (value) => {
  if (!value) {
    usdtAmount.value = ''
  } else if (amount.value && Number(amount.value) > 0) {
    usdtAmount.value = (Number(amount.value) / usdtRate.value).toFixed(2)
  }
})

const allAmount = () => {
  if (balance.value <= 0) {
    amount.value = ''
    usdtAmount.value = ''
    return
  }

  amount.value = balance.value.toFixed(2)

  if (isUsdt.value) {
    usdtAmount.value = (balance.value / usdtRate.value).toFixed(2)
  }
}

const goSupport = () => {
  router.visit(route('user.promotion.support'))
}

const openWithdrawPopup = () => {
  if (!currentWallet.value) {
    if (isUsdt.value) {
      goSupport()
    } else {
      router.visit(route('user.wallet.addWellet'))
    }
    return
  }

  if (!amount.value || Number(amount.value) <= 0) {
    window.alert('Please enter withdrawal amount')
    return
  }

  if (amountError.value) {
    window.alert(amountError.value)
    return
  }

  showPasswordPopup.value = true
}

const closeWithdrawPopup = () => {
  showPasswordPopup.value = false
  password.value = ''
  showPassword.value = false
}

const confirmWithdraw = () => {
  if (!currentWallet.value) {
    if (isUsdt.value) {
      goSupport()
    } else {
      router.visit(route('user.wallet.addWellet'))
    }
    return
  }

  if (!amount.value || Number(amount.value) <= 0) {
    window.alert('Please enter withdrawal amount')
    return
  }

  if (amountError.value) {
    window.alert(amountError.value)
    return
  }

  if (!password.value) {
    window.alert('Please enter your login password')
    return
  }

  submitting.value = true

  router.post(route('user.wallet.Withdraw.store'), {
    withdraw_wallet_id: currentWallet.value.id,
    amount: amount.value,
    password: password.value,
  }, {
    preserveScroll: true,
    onFinish: () => {
      submitting.value = false
      closeWithdrawPopup()
    }
  })
}

const actionButtonText = computed(() => 'Withdraw')
const actionHandler = () => {
  openWithdrawPopup()
}
</script>

